create schema if not exists sigov;

create table if not exists sigov.transito_agente (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,nome varchar(200) not null,matricula varchar(50) not null,cpf varchar(14) not null,telefone varchar(30),email varchar(200),cargo varchar(100) not null,status varchar(30) not null default 'ATIVO',data_inicio date not null,data_fim date,observacao text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,constraint ck_transito_agente_datas check(data_fim is null or data_fim>=data_inicio),unique(tenant_id,entity_id,matricula));
create table if not exists sigov.transito_condutor (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,nome varchar(200) not null,cpf varchar(14) not null,cnh varchar(30) not null,categoria_cnh varchar(10) not null,validade_cnh date not null,telefone varchar(30),email varchar(200),endereco text,status varchar(30) not null default 'ATIVO',observacao text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,cnh));
create table if not exists sigov.transito_veiculo (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,placa varchar(10) not null,renavam varchar(20),chassi varchar(30),marca varchar(80) not null,modelo varchar(100) not null,ano_fabricacao int,cor varchar(40),proprietario_nome varchar(200) not null,proprietario_documento varchar(20) not null,tipo_veiculo varchar(50) not null,status varchar(30) not null default 'ATIVO',observacao text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,placa));
create table if not exists sigov.transito_infracao_tipo (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,codigo varchar(30) not null,descricao text not null,gravidade varchar(30) not null,valor_multa numeric(14,2) not null check(valor_multa>=0),pontos int not null check(pontos>=0),base_legal text not null,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,codigo));
create table if not exists sigov.transito_auto_infracao (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,numero_auto varchar(50) not null,agente_id bigint not null references sigov.transito_agente(id),condutor_id bigint references sigov.transito_condutor(id),veiculo_id bigint references sigov.transito_veiculo(id),infracao_tipo_id bigint not null references sigov.transito_infracao_tipo(id),data_hora_infracao timestamptz not null,local_infracao text not null,latitude numeric(9,6) check(latitude between -90 and 90),longitude numeric(9,6) check(longitude between -180 and 180),descricao text not null,condutor_identificado boolean not null,justificativa_sem_condutor text,justificativa_sem_veiculo text,valor_multa numeric(14,2) not null check(valor_multa>=0),status varchar(30) not null default 'EMITIDO',justificativa_cancelamento text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,numero_auto),check(veiculo_id is not null or nullif(trim(justificativa_sem_veiculo),'') is not null),check((condutor_identificado and condutor_id is not null) or (not condutor_identificado and nullif(trim(justificativa_sem_condutor),'') is not null)),check(status not in ('CANCELADO','ANULADO') or nullif(trim(justificativa_cancelamento),'') is not null));
create table if not exists sigov.transito_notificacao (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,auto_infracao_id bigint not null references sigov.transito_auto_infracao(id),numero_notificacao varchar(50) not null,data_emissao date not null,data_vencimento date not null,meio_envio varchar(40) not null,destinatario_nome varchar(200) not null,destinatario_documento varchar(20) not null,endereco_envio text not null,status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,numero_notificacao),check(data_vencimento>=data_emissao));
create table if not exists sigov.transito_recurso (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,auto_infracao_id bigint not null references sigov.transito_auto_infracao(id),notificacao_id bigint references sigov.transito_notificacao(id),protocolo_recurso varchar(50) not null,requerente_nome varchar(200) not null,requerente_documento varchar(20) not null,data_recurso date not null,fundamento text not null,status varchar(30) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,protocolo_recurso));
create table if not exists sigov.transito_julgamento (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,recurso_id bigint not null references sigov.transito_recurso(id),data_julgamento date not null,resultado varchar(30) not null,relator_nome varchar(200) not null,fundamentacao text not null check(length(trim(fundamentacao))>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists sigov.transito_ocorrencia (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,tipo varchar(60) not null,data_hora timestamptz not null,local text not null,latitude numeric(9,6) check(latitude between -90 and 90),longitude numeric(9,6) check(longitude between -180 and 180),gravidade varchar(30) not null,descricao text not null,agente_id bigint references sigov.transito_agente(id),status varchar(30) not null,providencias text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists sigov.transito_sinalizacao (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,tipo varchar(60) not null,descricao text not null,local text not null,latitude numeric(9,6) check(latitude between -90 and 90),longitude numeric(9,6) check(longitude between -180 and 180),estado_conservacao varchar(40) not null,data_instalacao date,data_ultima_vistoria date,status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists sigov.transito_intervencao_viaria (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,titulo varchar(200) not null,tipo varchar(60) not null,local text not null,data_inicio date not null,data_fim_prevista date not null,data_fim_real date,responsavel varchar(200) not null,impacto text not null,status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,check(data_fim_prevista>=data_inicio),check(data_fim_real is null or data_fim_real>=data_inicio));
create table if not exists sigov.transito_linha_transporte (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,codigo varchar(30) not null,nome varchar(200) not null,tipo_transporte varchar(50) not null,operador varchar(200) not null,status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,codigo));
create table if not exists sigov.transito_parada_ponto (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,codigo varchar(30) not null,nome varchar(200) not null,endereco text not null,latitude numeric(9,6) check(latitude between -90 and 90),longitude numeric(9,6) check(longitude between -180 and 180),acessibilidade boolean not null default false,status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,codigo));
create table if not exists sigov.transito_rota_transporte (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,linha_id bigint not null references sigov.transito_linha_transporte(id),nome varchar(200) not null,sentido varchar(60) not null,distancia_km numeric(10,2) not null check(distancia_km>=0),tempo_estimado_min int not null check(tempo_estimado_min>=0),status varchar(30) not null,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
create table if not exists sigov.transito_rota_ponto (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,rota_id bigint not null references sigov.transito_rota_transporte(id) on delete cascade,ponto_id bigint not null references sigov.transito_parada_ponto(id),ordem int not null check(ordem>0),created_at timestamptz not null default now(),unique(tenant_id,entity_id,rota_id,ponto_id),unique(tenant_id,entity_id,rota_id,ordem));
create table if not exists sigov.transito_autorizacao_transporte (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,numero_autorizacao varchar(50) not null,tipo varchar(50) not null,titular_nome varchar(200) not null,titular_documento varchar(20) not null,veiculo_id bigint references sigov.transito_veiculo(id),linha_id bigint references sigov.transito_linha_transporte(id),data_emissao date not null,data_validade date not null,status varchar(30) not null,justificativa_cancelamento text,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,numero_autorizacao),check(data_validade>=data_emissao),check(status<>'CANCELADA' or nullif(trim(justificativa_cancelamento),'') is not null));
create table if not exists sigov.transito_vistoria_transporte (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,autorizacao_id bigint references sigov.transito_autorizacao_transporte(id),veiculo_id bigint not null references sigov.transito_veiculo(id),agente_id bigint references sigov.transito_agente(id),data_vistoria date not null,resultado varchar(30) not null,itens_verificados text not null,irregularidades text,prazo_regularizacao date,status varchar(30) not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,check(resultado<>'REPROVADA' or nullif(trim(irregularidades),'') is not null),check(prazo_regularizacao is null or prazo_regularizacao>=data_vistoria));
create table if not exists sigov.transito_credencial (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,numero_credencial varchar(50) not null,tipo varchar(50) not null,beneficiario_nome varchar(200) not null,beneficiario_documento varchar(20) not null,data_emissao date not null,data_validade date not null,status varchar(30) not null,justificativa_cancelamento text,observacao text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,entity_id,numero_credencial),check(data_validade>=data_emissao),check(status<>'CANCELADA' or nullif(trim(justificativa_cancelamento),'') is not null));
create table if not exists sigov.transito_auditoria (id bigint generated by default as identity primary key,tenant_id bigint not null,entity_id bigint not null,tabela varchar(100) not null,registro_id bigint,acao varchar(30) not null,usuario varchar(200) not null,dados_anteriores jsonb,dados_novos jsonb,created_at timestamptz not null default now());
create index if not exists ix_transito_agente_cpf on sigov.transito_agente(tenant_id,entity_id,cpf); create index if not exists ix_transito_condutor_cpf on sigov.transito_condutor(tenant_id,entity_id,cpf); create index if not exists ix_transito_veiculo_placa on sigov.transito_veiculo(tenant_id,entity_id,placa); create index if not exists ix_transito_veiculo_documento on sigov.transito_veiculo(tenant_id,entity_id,proprietario_documento); create index if not exists ix_transito_notificacao_documento on sigov.transito_notificacao(tenant_id,entity_id,destinatario_documento); create index if not exists ix_transito_recurso_documento on sigov.transito_recurso(tenant_id,entity_id,requerente_documento); create index if not exists ix_transito_autorizacao_documento on sigov.transito_autorizacao_transporte(tenant_id,entity_id,titular_documento); create index if not exists ix_transito_credencial_documento on sigov.transito_credencial(tenant_id,entity_id,beneficiario_documento);
insert into sigov.permissao(chave,descricao,modulo,ativo,created_at) select p,'Trânsito: '||replace(p,'_',' '),'transito',true,now() from unnest(array['TRANSITO_DASHBOARD_VIEW','TRANSITO_AGENTE_VIEW','TRANSITO_AGENTE_MANAGE','TRANSITO_CONDUTOR_VIEW','TRANSITO_CONDUTOR_MANAGE','TRANSITO_VEICULO_VIEW','TRANSITO_VEICULO_MANAGE','TRANSITO_INFRACAO_VIEW','TRANSITO_INFRACAO_MANAGE','TRANSITO_AUTO_VIEW','TRANSITO_AUTO_MANAGE','TRANSITO_NOTIFICACAO_VIEW','TRANSITO_NOTIFICACAO_MANAGE','TRANSITO_RECURSO_VIEW','TRANSITO_RECURSO_MANAGE','TRANSITO_OCORRENCIA_VIEW','TRANSITO_OCORRENCIA_MANAGE','TRANSITO_SINALIZACAO_VIEW','TRANSITO_SINALIZACAO_MANAGE','TRANSITO_INTERVENCAO_VIEW','TRANSITO_INTERVENCAO_MANAGE','TRANSITO_TRANSPORTE_VIEW','TRANSITO_TRANSPORTE_MANAGE','TRANSITO_VISTORIA_VIEW','TRANSITO_VISTORIA_MANAGE','TRANSITO_CREDENCIAL_VIEW','TRANSITO_CREDENCIAL_MANAGE','TRANSITO_RELATORIO_EXPORT','TRANSITO_AUDITORIA_VIEW']) p on conflict(chave) do update set descricao=excluded.descricao,modulo=excluded.modulo,ativo=true;
